from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    """Least Recently Used cache with a fixed capacity."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._cache: OrderedDict[Any, Any] = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        """Return the value for `key` if present, otherwise None."""
        if key not in self._cache:
            return None
        # Move accessed key to end (most recently used).
        self._cache.move_to_end(key)
        return self._cache[key]

    def put(self, key: Any, value: Any) -> None:
        """Insert or update `key` with `value`, evicting LRU item if needed."""
        if key in self._cache:
            # Update existing entry and mark as most recently used.
            self._cache[key] = value
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self.capacity:
                # Evict least recently used item (first item).
                self._cache.popitem(last=False)
            self._cache[key] = value

    def __contains__(self, key: Any) -> bool:
        return key in self._cache

    def __len__(self) -> int:
        return len(self._cache)


def test_lru_cache_basic() -> None:
    cache = LRUCache(2)
    assert cache.get("a") is None
    cache.put("a", 1)
    assert cache.get("a") == 1

    cache.put("b", 2)
